mapper.sql:
where 1 = 1

    and c.status = #{status}


    and c.complaint_type = #{complaintType}


    and c.priority = #{priority}


    and c.station_id = #{stationId}


    and c.charger_id = #{chargerId}


    and c.created_at >= cast(#{createdFrom} as date)


    and c.created_at < cast(#{createdTo} as date) + interval '1 day'


    and (
        c.title ilike concat('%', #{keyword}, '%')
        or c.content ilike concat('%', #{keyword}, '%')
        or c.station_name ilike concat('%', #{keyword}, '%')
        or c.charger_name ilike concat('%', #{keyword}, '%')
        or cast(c.complaint_id as varchar) = #{keyword}
        or m.member_name ilike concat('%', #{keyword}, '%')
        or m.user_id ilike concat('%', #{keyword}, '%')
    )

mapper.select:
select

from complaint c

where c.member_id = #{memberId}
  and c.complaint_id = #{complaintId}

select

from complaint c


order by c.created_at desc, c.complaint_id desc
limit #{limit}
offset #{offset}

select

from complaint c

where c.complaint_id = #{complaintId}
